-- Period study v2; read-only; 2026-09-05 through 2026-09-11 Asia/Shanghai.
-- Observation frame uses ended lessons in the available daily partitions.
-- See report for snapshot, completeness and denominator limitations.
WITH frame AS (SELECT school_uid,COUNT(1) AS scheduled_n,SUM(CASE WHEN class_status=3 THEN 1 ELSE 0 END) AS opened_n,SUM(CASE WHEN class_status=4 THEN 1 ELSE 0 END) AS cancelled_n FROM eo_pdviews.ods_ms_eo_os_eeo_course_class_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND class_btime>=1788537600 AND class_btime<1789142400 AND school_uid>0 GROUP BY school_uid HAVING SUM(CASE WHEN class_status=3 THEN 1 ELSE 0 END)>0), thresholds AS (SELECT percentile_approx(opened_n,0.3333333333) AS q1,percentile_approx(opened_n,0.6666666667) AS q2 FROM frame), strat AS (SELECT f.school_uid,f.scheduled_n,f.opened_n,f.cancelled_n,CASE WHEN f.opened_n<=t.q1 THEN 'low' WHEN f.opened_n<=t.q2 THEN 'mid' ELSE 'high' END AS stratum,t.q1,t.q2 FROM frame f CROSS JOIN thresholds t) SELECT stratum,COUNT(1) AS institutions,SUM(scheduled_n) AS scheduled_n,SUM(opened_n) AS opened_n,SUM(cancelled_n) AS cancelled_n,MIN(opened_n) AS min_opened,MAX(opened_n) AS max_opened,MAX(q1) AS q1,MAX(q2) AS q2 FROM strat GROUP BY stratum ORDER BY stratum LIMIT 3;
